(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zs-sj-prepa-ssrpf-j4-sfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zs-sj-prepa-ssrpf-j4-sfm\",\n \"titre\": \"Préparation D.E (J) · J4 SSR/PF SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 55,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n   \"sha256\": \"9ee0174cae6a310ff499e14b7685289c3bf3a2155e497e3971a6b1d18f45aa2e\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J SSR / PF · Prépa D.E J4 (SFM)\",\n     \"slug\": \"prepa-ssrpf-j4-sfm\",\n     \"pages\": \"\",\n     \"count\": 55,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"SSR / PF\",\n     \"source\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente allaite exclusivement son nouveau-né âgé de 18 jours. Elle souhaite débuter une contraception oestro-progestative combinée car elle craint les autres méthodes. A ce stade l'OMS? Préconise la catégorie 3\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Allaitement au sein à moins de 6 semaines du post-partum : les contraceptifs hormonaux combinés sont en catégorie 4 (risque inacceptable), pas 3. La catégorie 3 concerne l'allaitement entre 6 semaines et 6 mois.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (critères d'éligibilité) et « Groupes particuliers – post-partum »\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les pilules de quatrième génération contiennent du DIENOGEST\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les pilules de 4e génération contiennent comme progestatif de la drospirénone, de la chlormadinone, du diénogest ou du nomégestrol.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (classification)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On parle de génération des contraceptifs hormonaux combinés selon le type de progestérone utilisée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les COC sont classés en générations selon le type de progestatif : noréthistérone (1re), lévonorgestrel/norgestrel (2e), désogestrel/gestodène/norgestimate (3e), drospirénone… (4e).\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (classification)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le préservatif, la cape cervicale, le spermicide et le diaphragme sont des méthodes de barrières\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Méthodes de barrière : mécaniques (préservatifs masculin et féminin, cape cervicale, diaphragme) et chimiques (spermicides).\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Généralités sur la contraception » et « Méthodes de barrière »\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La palpation du sein se fait en position couchée, le bras du sein examiné replié sur la tête\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"C'est la position décrite dans le cours : la cliente est couchée, le bras du côté examiné replié sous ou sur la tête, ce qui étale le sein sur le gril costal.\\n\\nSource : Cours de SR/PF L2 (INFAS 2023), Consultation en PF (examen des seins)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme KY désire avoir des rapports sexuels non protégés avec son conjoint après la pose d'implant. Alors, elle ne doit pas attendre 24 heures pour tout rapport sexuel après la pose\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ». Le cours indique que les contraceptifs progestatifs, dont l'implant, sont efficaces dès les 24 premières heures quand ils sont posés au bon moment du cycle. Remarque : Le cours précise que si l'implant est posé plus de 7 jours après le début des règles, il faut une méthode d'appoint ou l'abstinence pendant 7 jours. L'énoncé est ambigu.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux progestatifs » (avantages et moment d'insertion)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le counseling se définit comme étant un entretien, une tête à tête qui a lieu dans un endroit calme au cours duquel une personne aide une autre personne à trouver et choisir une solution à son problème\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Définition du cours : le counseling est un « entretien conseil », un tête-à-tête… La correction nationale de la Prépa DE (les J) retient « Faux » parce que l'énoncé dit seulement « un entretien ».\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Counseling en PF » (définition)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La consultation en planification familiale est le processus par lequel un prestataire de services de planification familiale interagit avec un client pour choisir et utiliser une méthode contraceptive ou pour trouver une solution à un problème de santé sexuelle\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours dit « …pour trouver une solution à un problème de santé de la reproduction », et non de santé sexuelle.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Consultation en PF » (définition)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme RIA Sage-femme réfère une cliente qui présente un avortement provoqué septique avec un désir de contraception le DIU\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Avortement septique = catégorie 4 pour le DIU (contre-indiqué). La sage-femme doit référer pour traiter l'infection et proposer une autre méthode.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « DIU » (critères de recevabilité) et « Groupes particuliers – post-abortum »\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'examen des seins se fait méthodiquement quadrant par quadrant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le sein est divisé en 4 quadrants passant par le mamelon ; on palpe méthodiquement d'un quadrant à l'autre, mains à plat, puis le mamelon et les aires ganglionnaires.\\n\\nSource : Cours de SR/PF L2 (INFAS 2023), Consultation en PF (examen des seins) ; Clinique obstétricale L3 (fiche 3 : examen des seins)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les autres antécédents sont constitués des antécédents gynécologiques, obstétricaux et familiaux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans le tableau du cours, les antécédents gynécologiques et obstétricaux font partie des antécédents personnels. Les « autres antécédents » sont les antécédents familiaux, collatéraux et les ATCD et options en PF.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Consultation en PF » (tableau des antécédents)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'échographie est indiquée lorsque survient une infection après la pose d'un DIU\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Devant une infection après la pose d'un DIU, on fait une évaluation clinique (signes vitaux, examen abdominal et pelvien) et des examens de laboratoire, puis on traite par antibiotiques. L'échographie est réservée à la recherche du DIU (fils introuvables, perforation, expulsion).\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « DIU du post-partum » (gestion de l'infection et des problèmes de fils)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente oublie deux pilules oestro-progestatives consécutives (jours dix huit et dix neuf de sa plaquette de vingt un comprimés). Elle a eu un rapport non protégé au seizième jour du cycle. il faut jeter les comprimés restants de la période d'arrêt et enchaîner sans pause\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Quand les oublis surviennent pendant la dernière semaine de comprimés actifs, on finit les comprimés actifs et on enchaîne directement sur une nouvelle plaquette, sans faire la semaine d'arrêt (on jette les comprimés inactifs d'une plaquette de 28). Remarque : Le cours (COC) indique, en cas d'oubli de 2 pilules ou plus, de prendre 2 pilules par jour jusqu'à rattrapage et d'utiliser une méthode d'appoint pendant 7 jours.\\n\\nSource : (explication hors cours du projet ; le cours décrit seulement la prise de 2 comprimés par jour et la méthode d'appoint)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le DIU entraine les infections\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le risque d'infection génitale haute chez les utilisatrices du DIU est inférieur à 1 % ; il est surtout lié à l'insertion (20 premiers jours) et à une IST préexistante, puis il devient comparable à celui des non-utilisatrices.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « DIU du post-partum » (complications)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La pose du DIU est indiquée si à l'examen vous constatez un col sain\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Avant la pose, l'examen au spéculum et le toucher vaginal vérifient l'absence de contre-indication (infection, cervicite, cancer du col…). Un col sain permet la pose.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « DIU » (étape 1 de la pose)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le premier volet de la fiche de référence et contre référence est rempli par le médecin\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le 1er volet est rempli par le prestataire qui réfère ; le 2e volet est rempli par le médecin qui reçoit la cliente.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Organisation et gestion d'un centre de PF » (fiche de référence)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En quoi consiste principalement une approche « transformatrice de genre » appliquée à la GHM en milieu scolaire ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Réserver l'enseignement de l'hygiène menstruelle exclusivement aux enseignants de mathématiques.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Déconstruire les tabous culturels en éduquant l'ensemble de la communauté scolaire.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Interdire strictement aux élèves de prononcer le mot « règles » dans l'enceinte de l'établissement.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Limiter l'accès aux toilettes propres uniquement aux élèves ayant les meilleures notes académiques.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Déconstruire les tabous culturels en éduquant l'ensemble de la communauté scolaire.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Une approche transformatrice de genre cherche à changer les normes et les tabous qui entourent les règles, en impliquant toute la communauté scolaire (filles, garçons, enseignants, parents). Les autres propositions renforcent les tabous ou les inégalités.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher le principe de base du counseling chez le client\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La liberté de la méthode contraceptive\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La liberté de s'éclairé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le consentement exprimé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les droits du client\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Les droits du client\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Principes au niveau du client : droit au caractère privé et confidentiel, liberté de choisir la méthode, liberté de s'exprimer, consentement éclairé, droits du client, renforcement de ses capacités. Seule l'option d reprend exactement le cours ; les autres sont déformées.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Counseling en PF » (principes de base)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente de 29 ans fait retirer son implant à l'étonogestrel car elle souhaite planifier une grossesse avec son conjoint. Elle s'inquiète du temps nécessaire pour retrouver une fertilité normale. Que lui indiquez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"6 à 12 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Immédiat\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"2ans\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"3 cycles\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Immédiat\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'implant est une méthode réversible : la fécondité revient rapidement après le retrait. C'est l'injectable (DMPA) qui retarde le retour de la fécondité de plusieurs mois.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux progestatifs » (avantages et limites)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher le principe de base du counseling chez le prestataire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La maîtrise du débat\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le fait de tirer les leçons de l'exemple\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Demeurer positif, constructif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'éducation du passé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Demeurer positif, constructif\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Principes au niveau du prestataire : la maîtrise du sujet, le fait de tirer les leçons du passé mais aussi demeurer positif, constructif, optimiste, l'éducation par l'exemple. Les options a, b et d mélangent les mots.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Counseling en PF » (principes de base)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle affirmation concernant la contraception d'urgence hormonale chez l'adolescente est exacte ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Elle peut remplacer une contraception régulière et être utilisée toutes les semaines sans risque.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Elle nécessite obligatoirement une prescription médicale préalable par un spécialiste.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Elle provoque systématiquement une interruption médicale de grossesse en cas d'œuf déjà implanté.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Elle doit être administrée le plus tôt possible après le rapport non protégé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Elle doit être administrée le plus tôt possible après le rapport non protégé\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La contraception d'urgence est d'autant plus efficace qu'elle est prise tôt après le rapport non protégé. Elle ne doit pas être utilisée de façon répétée à la place d'une méthode régulière et n'interrompt pas une grossesse déjà implantée. Remarque : Dans le sujet, l'option c est notée « d} » (coquille).\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Groupes particuliers – contraception d'urgence »\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Nommer la phase du counseling où toutes les méthodes sont décrites\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Counseling initial\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Counseling spécifique à la méthode\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Counseling de suivi\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Counseling initial\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Counseling initial : fait à la réception du client, on décrit toutes les méthodes et on l'aide à choisir. Le counseling spécifique porte sur la méthode choisie ; le counseling de suivi, sur les visites suivantes.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Counseling en PF » (phases)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher les deux étapes du counseling qui se suivent\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rendez-vous\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Choix de méthode\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Renseignements\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Explication\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Choix de méthode ; D. Explication\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Dans BERCER, « C » (Choix de la méthode) est suivi de « E » (Explications). Les renseignements (R) précèdent le choix ; le rendez-vous (R) suit les explications.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Counseling en PF » (étapes BERCER)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente de 39 ans, en bonne santé par ailleurs, souhaite débuter une pilule oestro-progestative combinée. Elle fume activement 18 cigarettes par jour depuis l'âge de vingt ans. Quelle est la conduite à tenir selon l'OMS ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Prescription possible sous surveillance tensionnelle rapprochée.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Prescription autorisée si la patiente s'engage à réduire sa consommation de moitié.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Contre-indication absolue.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Utilisation sans restriction.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Contre-indication absolue.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Femme de 35 ans ou plus qui fume 15 cigarettes ou plus par jour : risque cardiovasculaire inacceptable avec un œstroprogestatif, la méthode ne doit pas être utilisée. On propose une méthode sans œstrogène.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (critères d'éligibilité, mode de vie)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher le but de la consultation en planification familiale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ne pas s'assurer que la cliente est enceinte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dépister les infections sexuelles\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Identifier les indications médicales\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Ne pas s'assurer que la cliente est enceinte\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient l'option a. Le but du cours est « s'assurer que la cliente n'est pas enceinte » ; l'option c déforme « identifier les contre-indications médicales ».\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Consultation en PF » (buts)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Il existe combien de groupes de contraceptifs hormonaux combinés\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"03\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"04\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"10\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"14\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 04\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours présente 4 CHC : contraceptifs oraux combinés (COC), patch combiné, anneau intravaginal combiné et injectables combinés (CIC).\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (définitions)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme GRO est sous contraceptif injectable contenant deux types d'hormones. Cocher le prochain rendez-vous\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rendez-vous dans quatre semaines\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rendez-vous dans huit semaines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rendez-vous dans douze semaines\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Rendez-vous dans quatre semaines\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un injectable à deux hormones est un contraceptif injectable combiné (CIC) : réinjection toutes les 4 semaines. Huit semaines = Noristérat ; douze semaines = Depo-Provera/Sayana Press.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (calendrier de suivi des CIC)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher l'élément de l'identité du client dans la consultation en planification familiale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Age en mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Niveau d'éducation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fonction\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Niveau d'éducation\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Identité du client : nom et prénoms, âge, niveau d'éducation, profession/occupation, domicile, situation matrimoniale et socio-économique. L'âge se note en années.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Consultation en PF » (interrogatoire)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente de 32 ans, tabagique sevrée, consulte pour une contraception hormonale combinée. Elle présente des migraines avec aura survenant deux fois par mois. Selon les critères d'éligibilité médicale de l'OMS, quelle est la classification de la CHC pour cette patiente ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Catégorie 1\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Catégorie 2\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Catégorie 4\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Catégorie 3\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Catégorie 4\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les migraines avec aura sont en catégorie 4 pour tous les CHC (COC, CIC, patch, anneau), quel que soit l'âge, à cause du risque d'AVC.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (critères d'éligibilité)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La méthode contraceptive spécifique pour l'adolescent est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"MAMA\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Condom\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Méthode chirurgicale volontaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Condom\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez les adolescents, le préservatif (masculin ou féminin) est la méthode la plus recommandée (+++) car il protège aussi contre les IST/VIH. La MAMA concerne le post-partum ; la CCV est définitive.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Groupes particuliers – contraception des adolescents »\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher l'élément qui figure sur la fiche de référence et contre référence\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La date\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le nom et la signature\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La conduite à tenir infirmière\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La date\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le 1er volet de la fiche porte notamment la date, le nom de la cliente, le n° de fiche, la méthode utilisée, le problème rencontré, le nom et la signature du prestataire. On n'y note pas de « conduite à tenir infirmière ».\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Organisation et gestion d'un centre de PF » (fiche de référence et contre-référence)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__31\",\n       \"num\": \"32\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : Une utilisatrice d'une pilule oestro-progestative monophasique oublie de prendre sa pilule du troisième jour de sa plaquette. Elle s'en aperçoit trente six heures plus tard (au moment de prendre la pilule suivante). Elle a eu un rapport sexuel non protégé 48 heures avant l'oubli.\",\n       \"text\": \"Quelle est la conduite immédiate à tenir ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Prendre immédiatement la pilule oubliée.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Jeter la plaquette en cours et recommencer un nouveau cycle immédiatement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Ne rien faire de particulier\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Attendre les prochaines règles.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Prendre immédiatement la pilule oubliée.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours : si l'on oublie une pilule active, il faut la prendre dès qu'on s'en rappelle, même si cela fait 2 pilules le même jour, puis continuer la plaquette.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (instructions COC)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__32\",\n       \"num\": \"33\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : Une utilisatrice d'une pilule oestro-progestative monophasique oublie de prendre sa pilule du troisième jour de sa plaquette. Elle s'en aperçoit trente six heures plus tard (au moment de prendre la pilule suivante). Elle a eu un rapport sexuel non protégé 48 heures avant l'oubli.\",\n       \"text\": \"Doit-elle continuer la plaquette ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Oui : après avoir pris la pilule oubliée, elle continue la plaquette à raison d'une pilule par jour.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (instructions COC)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__33\",\n       \"num\": \"34\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : Une utilisatrice d'une pilule oestro-progestative monophasique oublie de prendre sa pilule du troisième jour de sa plaquette. Elle s'en aperçoit trente six heures plus tard (au moment de prendre la pilule suivante). Elle a eu un rapport sexuel non protégé 48 heures avant l'oubli.\",\n       \"text\": \"Doit elle utiliser une contraception d'urgence ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Oui » : l'oubli concerne la 1re semaine de la plaquette (après la semaine d'arrêt) et il y a eu un rapport non protégé peu avant.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__34\",\n       \"num\": \"35\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : Une utilisatrice d'une pilule oestro-progestative monophasique oublie de prendre sa pilule du troisième jour de sa plaquette. Elle s'en aperçoit trente six heures plus tard (au moment de prendre la pilule suivante). Elle a eu un rapport sexuel non protégé 48 heures avant l'oubli.\",\n       \"text\": \"En cas de rapports sexuelles doit elle se protégée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Oui » : utiliser une méthode d'appoint (préservatif) pendant 7 jours, le temps que la pilule soit de nouveau efficace.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (instructions COC)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une utilisatrice sous COC qui présente des spottings après trois cycles doit être :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Examiner\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Référer\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Examiner\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les spottings sont fréquents et passagers pendant les 3 premiers mois ; s'ils persistent au-delà, il faut examiner la cliente (prise des pilules, autres causes gynécologiques) avant de décider.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (instructions de suivi et calendrier de suivi COC)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'examen gynécologique anormal chez une cliente sous contraception hormonale. Il faut\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Consultation prénatale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Référer\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Référer\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Une anomalie à l'examen gynécologique dépasse le cadre de la consultation de PF : on réfère la cliente vers le médecin, avec la fiche de référence.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Organisation et gestion d'un centre de PF » (fiche de référence) et arbres décisionnels des effets secondaires\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant la présence d'autres signes de grossesse chez une cliente après la troisième plaquette\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Examiner\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Référer\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Examiner\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Des signes de grossesse sous pilule imposent d'abord d'examiner la cliente (examen gynécologique, test de grossesse) pour confirmer ou éliminer une grossesse.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (signes avertisseurs) et arbres décisionnels\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le STEDIRIL contient\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"35 microgrammes EE\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"50 microgrammes EE\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"100 microgrammes EE\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 50 microgrammes EE\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le Stédiril est un COC normo-dosé : 50 µg d'éthinylestradiol (EE).\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (classification selon le dosage)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Une patiente sous pilule oestro-progestative souhaite passer à un implant sous-cutané. Elle a pris sa dernière pilule active hier et souhaite se faire poser l'implant aujourd'hui.\",\n       \"text\": \"Le prestataire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La rassure.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Lui dit d'attendre les règles.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Elle doit revenir dans sept jours.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Elle utilise une protection par préservatif.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La rassure.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Elle prenait correctement sa pilule : elle est protégée et l'implant peut être posé tout de suite, sans attendre les règles ni utiliser de méthode d'appoint. On la rassure.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux progestatifs » (moment d'administration) ; partiellement hors cours\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Une patiente sous pilule oestro-progestative souhaite passer à un implant sous-cutané. Elle a pris sa dernière pilule active hier et souhaite se faire poser l'implant aujourd'hui.\",\n       \"text\": \"La patiente est-elle protégée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Oui : la dernière pilule active a été prise hier, la protection de la pilule est encore assurée au moment de la pose.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Une patiente sous pilule oestro-progestative souhaite passer à un implant sous-cutané. Elle a pris sa dernière pilule active hier et souhaite se faire poser l'implant aujourd'hui.\",\n       \"text\": \"Le prestataire doit-il insérer l'implant ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Oui : le changement de méthode peut se faire immédiatement, on est certain qu'elle n'est pas enceinte.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux progestatifs » (« à n'importe quel moment si le prestataire est certain que la cliente n'est pas enceinte »)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme HI a opté le 01 janvier 2025 pour les Comprimés combinés. Elle a oublié la prise du 01 mars et a néanmoins continué sa méthode\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Protégée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non protégée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Référer\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Protégée\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un seul oubli, puis poursuite de la méthode : la protection est maintenue (le cours prévoit de prendre la pilule dès qu'on s'en rappelle et de continuer). Remarque : Dans le sujet, les options b et c portent deux fois leur lettre.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » (instructions COC)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme HI exige les préservatifs pendant les rapports sexuels avec son conjoint\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Normal\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Anormal\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Anormal\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Anormal » : Mme HI est déjà protégée par sa pilule, l'exigence du préservatif dans son couple n'a pas de justification contraceptive.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"29 mars 2025 Mme HI est sous contraceptif injectable progestatif. Car, elle a des migraines\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La décision est normale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La décision est anormale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La décision n'est pas rassurante\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La décision est normale\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les migraines contre-indiquent ou déconseillent les œstroprogestatifs (catégorie 3 ou 4), alors qu'elles sont en catégorie 2 pour les contraceptifs progestatifs. Passer à un injectable progestatif est donc normal.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux combinés » et « Contraceptifs hormonaux progestatifs » (critères d'éligibilité)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"07 juin 2025, Mme HI opte pour les Comprimés. Car, elle a manifesté une rougeur au point d'injection. La PI est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Accompli\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rigoureuse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Partielle\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Option 2\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Partielle\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Une rougeur au point d'injection traduit un défaut d'asepsie : la prévention des infections (PI) n'a été que partielle. Le cours demande de respecter la PI pour les injectables et les implants. Remarque : « Option 2 » est un choix vide laissé dans le sujet.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux progestatifs » (limites : respecter la PI)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme HI peut utiliser en 2026\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Contraception chirurgical volontaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"MAMA\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dispositif intra utérin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Dispositif intra utérin\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Après la pilule (refusée à cause des migraines) et l'injectable (réaction au point d'injection), le DIU au cuivre est une méthode non hormonale, de longue durée, sans risque lié aux migraines. La MAMA ne concerne que le post-partum ; la CCV est définitive.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « DIU » (avantages)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans quelle situation exceptionnelle le professionnel de santé est-il éthiquement et légalement amené à lever le secret médical concernant un(e) adolescent(e) ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Chaque fois que l'adolescent a une activité sexuelle avant 18 ans.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"En cas de danger immédiat pour la sécurité ou l'intégrité physique ou psychologique du mineur.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Lorsque les parents exigent de connaître le motif exact de la consultation.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Dès que l'adolescent refuse de dire ce qu'il a fait le week-end.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. En cas de danger immédiat pour la sécurité ou l'intégrité physique ou psychologique du mineur.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La confidentialité est la règle avec l'adolescent ; elle ne peut être levée qu'en cas de danger grave et immédiat pour le mineur (sévices, violences, risque vital).\\n\\nSource : (explication hors cours du projet ; le cours insiste sur la confidentialité avec les adolescents)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'outils de travail en planification familiale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le carnet de commande\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les fiches\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La carte\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Le carnet de commande\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le carnet de commande figure dans la liste des outils de travail en PF ; il sert à commander les contraceptifs et le matériel. Remarque : Le cours cite aussi des fiches (fiche individuelle, fiche de référence, fiche de rapport) et la carte de rendez-vous ; les options b et c sont trop vagues.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Organisation et gestion d'un centre de PF » (outils de travail)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__49\",\n       \"num\": \"50\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la méthode de BILLINGS, après l'ovulation la couleur de la glaire cervicale est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Trouble\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mitigée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Mélangée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Claire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Mélangée\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Tableau des changements de la glaire : après l'ovulation, elle est diminuée, fine et de couleur « mélangée ». Elle est claire (blanc d'œuf) à l'ovulation et trouble après les règles et avant les règles.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Méthodes d'auto-observation » (méthode de Billings)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__50\",\n       \"num\": \"51\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher deux caractéristiques différenciant le CIC de Sayana Press\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Contraceptif\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sous cutané\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Progestérone\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"intra dermique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Intra musculaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Sous cutané ; E. Intra musculaire\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Sayana Press s'injecte en sous-cutané ; les CIC s'injectent en intramusculaire. Ce sont deux contraceptifs injectables, la différence porte donc sur la voie d'injection.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux progestatifs » (tableau des injectables) et « CHC »\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__51\",\n       \"num\": \"52\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'implant est contre indiqué chez\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La pauci pare\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La nullipare\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La ménopausée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La ménopausée\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les femmes qui ont ou n'ont pas eu d'enfants sont en catégorie 1 pour l'implant. Une femme ménopausée n'a plus besoin de contraception : l'implant n'a pas d'indication chez elle.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux progestatifs » (critères d'éligibilité)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__52\",\n       \"num\": \"53\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Une patiente de 26 ans, porteuse d'un dispositif intra-utérin au lévonorgestrel depuis huit mois, consulte car elle n'a plus ses règles du tout depuis 4 mois. Elle s'inquiète d'une possible grossesse ou d'une pathologie.\",\n       \"text\": \"Quel est votre premier diagnostic ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ménopause précoce iatrogène\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Echec de la contraception\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Aménorrhée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"grossesse extra utérine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Aménorrhée\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le DIU hormonal au lévonorgestrel agit sur l'endomètre : il diminue les règles et peut entraîner une aménorrhée, effet attendu et sans gravité.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « DIU » (DIU hormonal) et « CHP » (aménorrhée)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__53\",\n       \"num\": \"54\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Une patiente de 26 ans, porteuse d'un dispositif intra-utérin au lévonorgestrel depuis huit mois, consulte car elle n'a plus ses règles du tout depuis 4 mois. Elle s'inquiète d'une possible grossesse ou d'une pathologie.\",\n       \"text\": \"Quelle est l'attitude du prestataire face à la patiente ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Retirer le dispositif intra utérin\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réaliser un curetage\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Rassurer\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'aménorrhée sous progestatif n'est pas grave et ne nécessite pas de traitement : on rassure la cliente (en s'assurant qu'il n'y a pas de grossesse si un doute existe).\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux progestatifs » (instructions : « rassurer la cliente que l'aménorrhée n'est pas grave »)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__54\",\n       \"num\": \"55\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cochez la qualité morale d'un bon conseiller\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Comprend les avantages de toutes les méthodes contraceptives\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Comprend les facteurs qui influencent le choix d'une méthode\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Encourage le client à poser des questions\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Encourage le client à poser des questions\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"« Encourage le client à poser des questions » figure tel quel dans la liste des qualités d'un bon conseiller. Remarque : Les options a et b sont des versions raccourcies d'autres qualités du cours (« comprend les avantages et les limitations… », « comprend les facteurs culturels et émotionnels… »).\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Counseling en PF » (qualités d'un bon conseiller)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
